<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('hunts.manage');$id=(int)input('id');$hunt=null;if($id){$s=db()->prepare('SELECT * FROM hunts WHERE id=?');$s->execute([$id]);$hunt=$s->fetch();if(!$hunt){http_response_code(404);exit('Hunt not found');}}
if(is_post()){verify_csrf();$title=trim((string)input('title'));$slug=strtolower(trim((string)input('slug')));$start=str_replace('T',' ',trim((string)input('start_at')));$end=str_replace('T',' ',trim((string)input('end_at')));$fee=trim((string)input('activation_fee'));$min=trim((string)input('reward_min'));$max=trim((string)input('reward_max'));$status=strtoupper((string)input('status'));if($title===''||!preg_match('/^[a-z0-9-]{3,190}$/',$slug)||!in_array($status,['DRAFT','ACTIVE','INACTIVE','ENDED'],true)||!strtotime($start)||!strtotime($end)||strtotime($end)<=strtotime($start)||!preg_match('/^\d{1,16}(\.\d{1,2})?$/',$fee)||!preg_match('/^\d{1,16}(\.\d{1,2})?$/',$min)||!preg_match('/^\d{1,16}(\.\d{1,2})?$/',$max)||decimal_compare($min,'0.00')<=0||decimal_compare($max,$min)<0)flash('error','Enter valid hunt dates, money ranges, status, title and slug.');else{try{$pdo=db();$pdo->beginTransaction();$values=[$title,$slug,trim((string)input('description')),trim((string)input('rules')),trim((string)input('featured_image'))?:null,$start,$end,$fee,$min,$max,$status];if($id){$pdo->prepare('UPDATE hunts SET title=?,slug=?,description=?,rules=?,featured_image=?,start_at=?,end_at=?,activation_fee=?,reward_min=?,reward_max=?,status=? WHERE id=?')->execute([...$values,$id]);}else{$pdo->prepare('INSERT INTO hunts(title,slug,description,rules,featured_image,start_at,end_at,activation_fee,reward_min,reward_max,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([...$values,admin()['id']]);$id=(int)$pdo->lastInsertId();}audit_log((int)admin()['id'],$hunt?'HUNT_UPDATED':'HUNT_CREATED','hunts',(string)$id,$hunt,$values);$pdo->commit();flash('success','Hunt saved.');redirect('/admin/hunts/manage.php?id='.$id);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error','Could not save hunt. The slug may already exist.');}}}
$pageTitle=$hunt?'Edit hunt':'New hunt';$pageSubtitle='All monetary ranges and status windows are enforced by the server';require APP_ROOT.'/includes/header.php';$val=static fn(string $k,string $d='')=>$hunt[$k]??$d;?>
<section class="panel"><form method="post" class="form-grid"><?=csrf_field()?><div class="field"><label>Title</label><input name="title" maxlength="190" value="<?=e($val('title'))?>" required></div><div class="field"><label>Slug</label><input name="slug" pattern="[a-z0-9-]{3,190}" value="<?=e($val('slug'))?>" required></div><div class="field full"><label>Description</label><textarea name="description"><?=e($val('description'))?></textarea></div><div class="field full"><label>Rules</label><textarea name="rules"><?=e($val('rules'))?></textarea></div><div class="field full"><label>Featured image URL/path</label><input name="featured_image" maxlength="255" value="<?=e($val('featured_image'))?>"></div><div class="field"><label>Starts</label><input type="datetime-local" name="start_at" value="<?=e(str_replace(' ','T',substr($val('start_at'),0,16)))?>" required></div><div class="field"><label>Ends</label><input type="datetime-local" name="end_at" value="<?=e(str_replace(' ','T',substr($val('end_at'),0,16)))?>" required></div><div class="field"><label>Activation fee</label><input name="activation_fee" inputmode="decimal" value="<?=e($val('activation_fee','0.00'))?>" required></div><div class="field"><label>Reward minimum</label><input name="reward_min" inputmode="decimal" value="<?=e($val('reward_min','10.00'))?>" required></div><div class="field"><label>Reward maximum</label><input name="reward_max" inputmode="decimal" value="<?=e($val('reward_max','100.00'))?>" required></div><div class="field"><label>Status</label><select name="status"><?php foreach(['DRAFT','ACTIVE','INACTIVE','ENDED'] as $v):?><option <?=$val('status','DRAFT')===$v?'selected':''?>><?=e($v)?></option><?php endforeach?></select></div><div class="field full"><button class="btn">Save hunt</button></div></form></section><?php require APP_ROOT.'/includes/footer.php';
